// DimTicketCategory — generated by src/powerbi/build_assets.py from DimTicketCategory.csv
// Grain/keys: see powerbi/data_model.md
let
    Source   = Csv.Document(File.Contents(DataFolder & "DimTicketCategory.csv"),
                            [Delimiter = ",", Encoding = 65001, QuoteStyle = QuoteStyle.Csv]),
    Promoted = Table.PromoteHeaders(Source, [PromoteAllScalars = true]),
    Typed    = Table.TransformColumnTypes(Promoted, {
        {"category_key", Int64.Type},
        {"ticket_category", type text},
        {"ticket_subcategory", type text}
    }, "en-US")
in
    Typed
